package org.localscape.nylocas.ranger;
import org.junit.Test;
import org.localscape.nylocas.ranger.RangerStrategy.*;
import static org.junit.Assert.*;
public class RangerFiniteFreshOpportunityTest {
 private Crab old;
 private Crab add(Room r,int key,int born,int wave,Lane lane,char slot,boolean big,Style style,int x,int y){Crab c=new Crab(key,key,born,wave,lane,slot,big,style,RangerStrategy.tile(x,y));c.pendingDamage=0;r.crabs.add(c);return c;}
 private Room beforeNine(){Room r=new Room();r.wave=8;r.spawns[8]=52;r.ready=54;r.player=RangerStrategy.tile(3295,4248);old=add(r,1,20,4,Lane.SPLIT,(char)0,false,Style.MAGIC,3295,4247);return r;}
 private void assertHold(Decision d){assertNull(d.reason,d.target);assertTrue(d.reason,d.reason.startsWith("Prepare finite fresh opportunity"));}
 @Test public void nextAssignedEastNineLaneCanUseTwoReadyTicks(){Room r=beforeNine();RangerStrategy s=new RangerStrategy();Decision d=s.decide(r,54);assertHold(d);assertEquals(Weapon.EYE,d.weapon);assertEquals(3301,d.tile.getX());r.player=RangerStrategy.tile(3297,4248);assertHold(s.decide(r,55));}
 @Test public void waveAndOpportunityChangesCannotRestartTheTwoReadyTickBudget(){Room r=beforeNine();RangerStrategy s=new RangerStrategy();assertHold(s.decide(r,54));r.player=RangerStrategy.tile(3297,4248);assertHold(s.decide(r,55));r.wave=9;r.spawns[9]=56;r.player=RangerStrategy.tile(3295,4248);add(r,2,56,9,Lane.SPLIT,(char)0,false,Style.RANGE,3303,4248);assertSame(old,s.decide(r,56).target);}
 @Test public void repeatedCallsInOneTickDoNotConsumeAnotherReadyTick(){Room r=beforeNine();RangerStrategy s=new RangerStrategy();assertHold(s.decide(r,54));assertHold(s.decide(r,54));r.player=RangerStrategy.tile(3297,4248);assertHold(s.decide(r,55));}
 @Test public void realAttackRenewsTheBudget(){Room r=beforeNine();RangerStrategy s=new RangerStrategy();assertHold(s.decide(r,54));r.player=RangerStrategy.tile(3297,4248);assertHold(s.decide(r,55));r.wave=9;r.spawns[9]=56;r.player=RangerStrategy.tile(3295,4248);Crab fresh=add(r,2,56,9,Lane.SPLIT,(char)0,false,Style.RANGE,3303,4248);Decision shot=s.decide(r,56);assertSame(old,shot.target);s.attacked(shot,56);r.crabs.remove(old);old=add(r,3,31,5,Lane.SPLIT,(char)0,false,Style.MAGIC,3295,4247);r.ready=59;Decision next=s.decide(r,59);assertTrue(next.reason,next.target==fresh||next.approach==fresh);}
 @Test public void resetRenewsTheBudget(){Room r=beforeNine();RangerStrategy s=new RangerStrategy();assertHold(s.decide(r,54));r.player=RangerStrategy.tile(3297,4248);assertHold(s.decide(r,55));s.reset();assertHold(s.decide(r,54));}
 @Test public void cooldownStagingDoesNotSpendTheReadyAllowance(){Room r=beforeNine();r.ready=56;RangerStrategy s=new RangerStrategy();assertHold(s.decide(r,54));r.player=RangerStrategy.tile(3297,4248);assertHold(s.decide(r,55));r.wave=9;r.spawns[9]=56;r.player=RangerStrategy.tile(3295,4248);Crab fresh=add(r,2,56,9,Lane.SPLIT,(char)0,false,Style.RANGE,3303,4248);Decision d=s.decide(r,56);assertTrue(d.reason,d.target==fresh||d.approach==fresh);}
 @Test public void anUnknownLaneTimestampCannotInventANewSpawn(){Room r=beforeNine();r.spawns[8]=-1;assertSame(old,new RangerStrategy().decide(r,54).target);}
 @Test public void equalTimeFreshReplacesAnUnhitOldCommitment(){Room r=new Room();r.wave=9;r.spawns[9]=56;r.player=RangerStrategy.tile(3295,4248);r.ready=61;r.player=RangerStrategy.tile(3295,4248);old=add(r,1,32,5,Lane.SPLIT,(char)0,false,Style.RANGE,3294,4248);RangerStrategy s=new RangerStrategy();s.decide(r,60);Crab fresh=add(r,2,61,9,Lane.SPLIT,(char)0,false,Style.RANGE,3296,4248);assertSame(fresh,s.decide(r,61).target);}
 @Test public void anActualOldSurvivorStillGetsItsFollowup(){Room r=new Room();r.wave=9;r.spawns[9]=56;r.player=RangerStrategy.tile(3295,4248);r.ready=61;r.player=RangerStrategy.tile(3295,4248);old=add(r,1,32,5,Lane.SPLIT,(char)0,false,Style.RANGE,3294,4248);RangerStrategy s=new RangerStrategy();s.attacked(new Decision(old,Weapon.PIPE,r.player,false,null,"actual prior attack"),59);old.hp=3;old.pendingDamage=0;add(r,2,61,9,Lane.SPLIT,(char)0,false,Style.RANGE,3296,4248);assertSame(old,s.decide(r,61).target);}
 @Test public void rawQueuedLethalDamageIsNotAnImminentSplitForecast(){Room r=new Room();r.wave=7;r.spawns[7]=40;r.ready=45;r.player=RangerStrategy.tile(3295,4248);old=add(r,1,12,3,Lane.SPLIT,(char)0,false,Style.MAGIC,3295,4247);Crab parent=add(r,2,16,4,Lane.SOUTH,'W',true,Style.MAGIC,3292,4244);parent.pendingDamage=16;assertSame(old,new RangerStrategy().decide(r,45).target);}
 @Test public void observedLateCombatDeathCanStageButNeverWaitPastItsBudget(){Room r=new Room();r.wave=7;r.spawns[7]=40;r.ready=40;r.player=RangerStrategy.tile(3295,4248);Crab parent=add(r,2,16,4,Lane.SOUTH,'W',true,Style.MAGIC,3292,4244);parent.hp=0;parent.dying=true;RangerStrategy s=new RangerStrategy();s.decide(r,40);old=add(r,1,12,3,Lane.SPLIT,(char)0,false,Style.MAGIC,3295,4247);assertHold(s.decide(r,45));assertHold(s.decide(r,46));assertSame(old,s.decide(r,47).target);}
 @Test public void actualExpiryAnimationHasAFiniteKnownChildBirth(){Room r=new Room();r.wave=14;r.spawns[14]=100;r.ready=105;r.player=RangerStrategy.tile(3295,4248);old=add(r,1,70,10,Lane.SPLIT,(char)0,false,Style.MAGIC,3295,4247);add(r,2,52,8,Lane.WEST,'S',true,Style.MAGIC,3292,4251);assertHold(new RangerStrategy().decide(r,105));}
 @Test public void partnerNullRescueIsProtectedFromOrdinaryFreshWaiting(){Room r=beforeNine();old.partnerNulled=true;assertSame(old,new RangerStrategy().decide(r,54).target);}
}
